	public bool Ack()
	{
		string cmd = "CUSTOMACK";
		object content = null;
		string version = "1.0";
		string text = "A4A3A2A1";
		if (!XSend(Xml.XmlCmd.CreateCmd(cmd, (Dictionary<string, List<string>>)content, version)))
		{
			return false;
		}
		Xml.GetResponse();
		string response = Xml.GetResponse(raw: true);
		Xml.GetResponse();
		Xml.Ack();
		Xml.GetResponse();
		Ack();
		Console.WriteLine(response);
		return response == text;
	}

	private int opMovToOffset(int firstOp, int secondOp, uint registerIndex)
	{
		int num = (firstOp & 0xF000) >> 12;
		int num2 = (secondOp & 0xF000) >> 12;
		int num3 = (firstOp & 0xF00000) >> 20;
		int num4 = (secondOp & 0xF00000) >> 20;
		int num5 = (((secondOp & 0xF0000) >> 4) | (secondOp & 0xFFF)) << num4 * 4;
		int num6 = (((firstOp & 0xF0000) >> 4) | (firstOp & 0xFFF)) << num3 * 4;
		if (num != num2 || num2 != registerIndex)
		{
			int num7 = -1;
			return -1;
		}
		return num5 | num6;
	}

	private (int, int) offsetToOpMov(int addr, int registerIndex, uint baseAddr)
	{
		int num = (int)(addr + baseAddr);
		int num2 = ((((num & 0xFFFF) >> 12) & 0xF) << 16) | (registerIndex << 14) | (num & 0xFFF);
		num >>= 16;
		int num3 = ((((num & 0xFFFF) >> 12) & 0xF) << 16) | (registerIndex << 14) | (num & 0xFFF) | 0x400000;
		int item = -486539264 + num2;
		int item2 = -486539264 + num3;
		return (item, item2);
	}

